import system
SOURCE = "[MQTT Engine]AIS/ais"

nodes = system.tag.browse(
    SOURCE,
    {"recursive": True, "tagType": "AtomicTag"}
).getResults()

paths = sorted(unicode(node["fullPath"]) for node in nodes)

if not paths:
    return []

readings = system.tag.readBlocking(paths, 5000)
vessels = {}

for path, reading in zip(paths, readings):
    # Structure: route / vessel folder / field
    relativePath = path[len(SOURCE) + 1:]
    parts = relativePath.split("/")

    if len(parts) != 3:
        continue

    route, folderId, field = parts
    key = (route, folderId)

    if key not in vessels:
        vessels[key] = {
            "route": route,
            "folderId": folderId,
            "tagPath": SOURCE + "/" + route + "/" + folderId
        }

    vessels[key][field] = (
        reading.value if reading.quality.isGood() else None
    )

return [vessels[key] for key in sorted(vessels)]

