timeoutSeconds = 300
markers = []

for vessel in value:
    try:
        positionMillis = OffsetDateTime.parse(
            unicode(vessel["msgtime"])
        ).toInstant().toEpochMilli()

        ageSeconds = (nowMillis - positionMillis) / 1000.0

        if ageSeconds < 0 or ageSeconds > timeoutSeconds:
            continue

        latitude = float(vessel["latitude"])
        longitude = float(vessel["longitude"])

        if not (-90 <= latitude <= 90):
            continue
        if not (-180 <= longitude <= 180):
            continue

        if vessel["mmsi"] is None:
            continue

        mmsi = unicode(vessel["mmsi"])
        route = unicode(vessel["route"])
        shipName = unicode(vessel["name"] or mmsi)

        # Prefer heading; fall back to course when unavailable.
        heading = vessel.get("trueHeading")
        if heading is None or not (0 <= float(heading) < 360):
            heading = vessel.get("courseOverGround")

        rotation = 0
        if heading is not None and 0 <= float(heading) < 360:
            rotation = float(heading)

        # Preserve all vessel fields for events and vessel details.
        properties = {}
        for field in vessel:
            properties[unicode(field)] = vessel[field]

        markers.append({
            "name": u"%s:%s" % (route, mmsi),
            "properties": properties,
            "enabled": True,
            "lat": latitude,
            "lng": longitude,
            "opacity": 1,
            "icon": {
                "path": "material/navigation",
                "color": "#4190F7",
                "rotate": rotation,
                "size": {
                    "width": 36,
                    "height": 36
                },
                "style": {
                    "classes": ""
                }
            },
            "event": {
                "stopPropagation": False
            },
            "tooltip": {
